package main

import (
	"gno.land/r/gov/dao"
	validators "gno.land/r/sys/validators/v0"
)

func main(cur realm) {
	pr := validators.NewValidatorProposalRequest(cross(cur),
		[]validators.ValoperChange{validators.NewValoperChange(address("g1xqwtx7typgztlwtqzqqungq6lpy5k3a9p8djxp"), 0)},
		"Eject validator samourai-crew-4 (g155yu85dl2rygemkxcvn3g26nfw0rr5y2dkj6m0) from the valset [fixture 1]",
		"Automated ejection proposal generated by katana (e2e fixture capture).\nScore: 12/100 over current_week",
	)
	dao.MustCreateProposal(cross(cur), pr)
}

